```python
def find_path(graph, start, goal):
    # Convert the undirected graph to an adjacency matrix
    adjacency_matrix = {}
    for node, neighbors in graph.items():
        adjacency_matrix[node] = {neighbor: True for neighbor in neighbors}
        for neighbor in neighbors:
            if neighbor != node:
                adjacency_matrix[neighbor][node] = True

    # DFS function to find the path
    def dfs(current, path):
        # If we reach the goal, we have found a path
        if current == goal:
            return path + [goal]

        # Mark the current node as visited
        for neighbor in adjacency_matrix[current]:
            if neighbor not in path:
                # Recursively explore the neighbor
                result = dfs(neighbor, path + [current])
                if result is not None:
                    return result
        return None

    # Start the DFS from the start node
    return dfs(start, [start])

# Example usage:
graph = {
    'A': ['B', 'C'],
    'B': ['D', 'E'],
    'C': ['F'],
    'D': [],
    'E': ['F'],
    'F': []
}

start_node = 'A'
goal_node = 'F'

path = find_path(graph, start_node, goal_node)
print(f"Path from {start_node} to {goal_node}: {path}")
