def find_path(graph, start, goal):
    def dfs(graph, start, goal, path=None):
        if path is None:
            path = [start]
        if start == goal:
            return path
        for node in graph[start]:
            if node not in path:
                new_path = dfs(graph, node, goal, path + [node])
                if new_path:
                    return new_path
        return None

    # Start the DFS if start node is not goal
    if start != goal:
        path = dfs(graph, start, goal)
    else:
        path = [start]

    return path if path else None

